const SPHINX = "sphinx";
const BASE_SPHINX_SCORE = 2;
const TYPES_FOR_BASE_SCORE = 3;

/**
 * A card's monster type ignores its rank: Undead Warrior (1) and
 * Undead Warrior (3) are the same type.
 */
const distinctMonsterTypes = (army: Card[]): Set<string> =>
  new Set(army.map((card) => card.monster));

/**
 * Beyond three distinct types the Sphinx scores on a steeper curve.
 * Fitted to the examples so far (5 types → 3, 6 types → 5); no example
 * yet pins down 4 types, where this formula happens to dip below the base.
 */
const bonusScoreFor = (typeCount: number): number =>
  (typeCount - TYPES_FOR_BASE_SCORE) * 2 - 1;

export const scoreArmy = (army: Card[]): number => {
  const types = distinctMonsterTypes(army);
  if (!types.has(SPHINX)) return 0;
  if (types.size <= TYPES_FOR_BASE_SCORE) return BASE_SPHINX_SCORE;
  return bonusScoreFor(types.size);
};
